// Rebuilds the page from Webflow's stored element tree + styles, renders it, and compares to the original
// Usage (from a folder holding wf-styles.txt, wf-tree.txt, assets.json): node webflow-verify.cjs
const fs = require('fs'); const { chromium } = require('playwright');
const J = (f) => { const t = fs.readFileSync(f, 'utf8'); return JSON.parse(t.slice(t.indexOf('{'))); };
const styles = J('wf-styles.txt').result;
const root = J('wf-tree.txt').result[0].data;
const assets = JSON.parse(fs.readFileSync('assets.json', 'utf8'));
const assetUrl = {}; for (const u of Object.values(assets)) { const m = u.match(/\/([0-9a-f]{24})_/); if (m) assetUrl[m[1]] = u; }
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const attrq = (s) => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
const VOID = new Set(['img', 'path', 'stop', 'circle', 'ellipse']);
let missingAsset = 0;
function html(n) {
  const s = n.settings || {}; let tag, attrs = { ...(n.attributes || {}) };
  const cls = (n.styleNames || []).slice();
  switch (n.type) {
    case 'String': return esc(n.textContent || '');
    case 'Body': return (n.children || []).map(html).join('');
    case 'Link': tag = 'a'; if (s.link && s.link.href) attrs.href = s.link.href; if ((n.children || []).some((c) => c.type !== 'String')) cls.push('w-inline-block'); break;
    case 'Image': tag = 'img'; attrs.src = assetUrl[s.assetId] || ''; if (!assetUrl[s.assetId]) missingAsset++; attrs.alt = s.altText || ''; break;
    case 'Heading': tag = s.tag || 'h2'; break;
    case 'Paragraph': tag = 'p'; break;
    case 'Blockquote': tag = 'blockquote'; break;
    case 'ListItem': tag = 'li'; break;
    case 'List': tag = s.tag || 'ul'; break;
    case 'Strong': tag = 'strong'; break;
    case 'Span': tag = 'span'; break;
    default: tag = s.tag || 'div';
  }
  if (cls.length) attrs.class = cls.join(' ');
  const a = Object.entries(attrs).map(([k, v]) => ` ${k}="${attrq(v)}"`).join('');
  const kids = (n.children || []).map(html).join('');
  if (VOID.has(tag) && !kids) return tag === 'img' ? `<img${a}>` : `<${tag}${a}></${tag}>`;
  return `<${tag}${a}>${kids}</${tag}>`;
}
const BP = { medium: 991, small: 767, tiny: 479 };
const fix = (k, v) => k === 'font-family' && !/[,'"]/.test(v) ? `'${v}', 'Helvetica Neue', Arial, sans-serif` : v;
const decl = (o) => Object.entries(o || {}).map(([k, v]) => `${k}:${fix(k, v)}`).join(';');
let css = '';
const med = { medium: '', small: '', tiny: '' };
for (const st of styles) {
  const p = st.properties || {};
  const base = p.base || {};
  if (base.properties) css += `${st.selector}{${decl(base.properties)}}`;
  const bh = base.pseudos && base.pseudos.hover; if (bh) css += `${st.selector}:hover{${decl(bh)}}`;
  for (const bp of Object.keys(BP)) {
    const b = p.breakpoints && p.breakpoints[bp]; if (!b) continue;
    if (b.properties) med[bp] += `${st.selector}{${decl(b.properties)}}`;
    const h = b.pseudos && b.pseudos.hover; if (h) med[bp] += `${st.selector}:hover{${decl(h)}}`;
  }
}
for (const bp of Object.keys(BP)) css += `@media screen and (max-width:${BP[bp]}px){${med[bp]}}`;
const WF = `html{font-size:16px}body{margin:0;min-height:100%;font-family:Arial,sans-serif;font-size:14px;line-height:20px;color:#333;background:#fff}*{box-sizing:border-box}h1{font-size:38px;line-height:44px;margin:20px 0 10px;font-weight:bold}h2{font-size:32px;line-height:36px;margin:20px 0 10px;font-weight:bold}h3{font-size:24px;line-height:30px;margin:20px 0 10px;font-weight:bold}p{margin:0 0 10px}img{max-width:100%;vertical-align:middle;display:inline-block}a{background-color:transparent}ul,ol{margin:0 0 10px;padding-left:40px}blockquote{margin:0 0 10px;padding:10px 20px;border-left:5px solid #e2e2e2;font-size:18px;line-height:22px}.w-inline-block{max-width:100%;display:inline-block}
@font-face{font-family:'Space Grotesk';src:url('data:font/woff2;base64,');font-weight:300 700}@font-face{font-family:'DM Sans';src:url('data:font/woff2;base64,');font-weight:100 1000}@font-face{font-family:'Manrope';src:url('data:font/woff2;base64,');font-weight:200 800}`;
fs.writeFileSync('recon.html', `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>${WF}</style><style>${css}</style></head><body>${html(root)}</body></html>`);
console.log('missing assets', missingAsset, 'html', fs.statSync('recon.html').size);
const SEL = ['.navbar', '.section_hero', '.ribbon', '.section_statement', '.section_gallery', '.section_work', '.section_keep-going', '.section_services-fan', '.section_testimonials, main > section:nth-of-type(8)', '.section_faq, main > section:nth-of-type(9)', '.footer'];
async function measure(page) { return page.evaluate((SEL) => SEL.map((s) => { const e = document.querySelector(s); if (!e) return [s, null]; const r = e.getBoundingClientRect(); return [s, Math.round(r.top + scrollY), Math.round(r.height)]; }), SEL); }
(async () => {
  const b = await chromium.launch();
  for (const w of [1440, 390]) {
    const ctx = await b.newContext({ viewport: { width: w, height: 900 }, isMobile: w < 800, javaScriptEnabled: false });
    const o = await ctx.newPage(); await o.goto('http://localhost:4321/index.html'); await o.evaluate(() => { document.documentElement.className = ''; document.querySelectorAll('.preloader,.transition,.cursor').forEach(e=>e.remove()); }); await o.waitForTimeout(1500);
    const r = await ctx.newPage(); await r.goto('file://' + process.cwd() + '/recon.html'); await r.waitForTimeout(2500); await r.evaluate(()=>document.fonts.ready);
    const mo = await measure(o), mr = await measure(r);
    console.log(`\n== ${w}px  section: original(top,h) vs webflow(top,h)`);
    mo.forEach((x, i) => console.log(x[0].split(',')[0].padEnd(24), JSON.stringify(x.slice(1)).padEnd(14), JSON.stringify(mr[i].slice(1)), mr[i][2] != null && x[2] != null && Math.abs(mr[i][2] - x[2]) > 4 ? '  <-- DIFF ' + (mr[i][2] - x[2]) : ''));
    await o.screenshot({ path: `orig-${w}.png`, fullPage: true }); await r.screenshot({ path: `wf-${w}.png`, fullPage: true });
    await ctx.close();
  }
  await b.close();
})();
